<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>GALAGA</title>
<style>
  html,body{margin:0;padding:0;background:#000;height:100%;overflow:hidden}
  body{display:flex;align-items:center;justify-content:center}
  canvas{image-rendering:pixelated;image-rendering:crisp-edges;background:#000;display:block}
</style>
</head>
<body>
<canvas id="c" width="224" height="288"></canvas>
<script>
"use strict";
/* =====================================================================
   GALAGA clone - single file. Logical resolution 224x288.
   Sections: constants, sprites, audio, input, state, paths, update, render
   ===================================================================== */
const W = 224, H = 288;
const cv = document.getElementById('c');
const ctx = cv.getContext('2d');
ctx.imageSmoothingEnabled = false;

function resize() {
  const s = Math.max(1, Math.min(Math.floor(window.innerWidth / W * 100) / 100, Math.floor(window.innerHeight / H * 100) / 100));
  const k = Math.max(1, Math.floor(Math.min(window.innerWidth / W, window.innerHeight / H)));
  const use = (k >= 1 && Math.min(window.innerWidth / W, window.innerHeight / H) >= 1) ? k : s;
  cv.style.width = (W * use) + 'px';
  cv.style.height = (H * use) + 'px';
}
window.addEventListener('resize', resize); resize();

/* ------------------------------ sprites ------------------------------ */
// Pixel art as string arrays. Palette characters map to colours.
const PAL = {
  '.': null,
  'w': '#ffffff', 'r': '#ff2020', 'R': '#a00000', 'b': '#2060ff', 'B': '#0030a0',
  'c': '#20e0ff', 'y': '#ffe020', 'Y': '#c09000', 'g': '#20d040', 'G': '#108020',
  'p': '#c040ff', 'P': '#702090', 'o': '#ff8020', 'k': '#808080', 'W': '#c0c0c0'
};
function makeSprite(rows, pal) {
  const h = rows.length, w = rows[0].length;
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const g = c.getContext('2d');
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const ch = rows[y][x]; const col = (pal || PAL)[ch];
    if (col) { g.fillStyle = col; g.fillRect(x, y, 1, 1); }
  }
  return c;
}
// recolour a palette
function remap(rows, map) { return rows.map(r => r.split('').map(ch => map[ch] || ch).join('')); }

// Player fighter 15x16
const SPR_PLAYER = [
"......www......",
"......www......",
"......www......",
".....wwwww.....",
".....wwcww.....",
"..w..wwcww..w..",
"..w..wwwww..w..",
".www.wwwww.www.",
".wwwwwwwwwwwww.",
"wwwwwwwwwwwwwww",
"wrwwwwwwwwwwwrw",
"wrwwwrwwwrwwwrw",
"wr.wwrwwwrww.rw",
"w..ww.rrr.ww..w",
"...rr.....rr...",
"...rr.....rr..."
];
// Zako (bee) 13x10 two frames
const ZAKO_A = [
"....y...y....",
".....y.y.....",
"...bbbbbbb...",
"..bbwbbbwbb..",
"bbbbrbbbrbbbb",
"bb.bbbbbbb.bb",
"b..bbyyybb..b",
"...bb.y.bb...",
"..bb.....bb..",
"..b.......b.."
];
const ZAKO_B = [
"....y...y....",
".....y.y.....",
"...bbbbbbb...",
"..bbwbbbwbb..",
".bbbrbbbrbbb.",
"bbbbbbbbbbbbb",
"b.bbbyyybbb.b",
"..bbb.y.bbb..",
"...bb...bb...",
"....b.....b.."
];
// Goei (butterfly) 15x12
const GOEI_A = [
"..r.........r..",
"..rr.......rr..",
"..rrr.....rrr..",
".rrwrr.y.rrwrr.",
".rrrrrryrrrrrr.",
"rrrBrrryrrrBrrr",
"rr.rrrrrrrrr.rr",
"r..rrBrrrBrr..r",
"...rrrrrrrrr...",
"....rr.r.rr....",
".....r...r.....",
"...............".substring(0,15)
];
const GOEI_B = [
"...............",
"..r.........r..",
".rrr..y.y..rrr.",
".rrwrr.y.rrwrr.",
"rrrrrrryrrrrrrr",
"rrrBrrryrrrBrrr",
"rrrrrrrrrrrrrrr",
".rrrrBrrrBrrrr.",
"..rrrrrrrrrrr..",
"...rrr.r.rrr...",
"....rr...rr....",
"....r.....r...."
];
// Boss Galaga 15x14 (green) and hit variant (blue/purple)
const BOSS_A = [
"..y.........y..",
".yyy.......yyy.",
".ygyy.....yygy.",
".gggg.ggg.gggg.",
".gwggggggggwgg.",
"gggggwgggwggggg",
"ggrgggggggggrgg",
"gg.gggGgGggg.gg",
"g..ggggggggg..g",
"...gg.ggg.gg...",
"..gg..g.g..gg..",
"..g...g.g...g..",
"..............."
].map(r => r);
const BOSS_B = [
"..y.........y..",
".yyy.......yyy.",
".ygyy.....yygy.",
".ggggggggggggg.",
"ggwgggggggggwgg",
"gggggwgggwggggg",
"ggrgggggggggrgg",
".ggggggGgGgggg.",
"..gggggggggggg.",
"...gg.ggg.gg...",
"....g.g.g.g....",
"....g.....g....",
"..............."
];
const toHit = rows => remap(rows, { 'g': 'b', 'G': 'B', 'y': 'p', 'r': 'y' });

const S = {
  player: makeSprite(SPR_PLAYER),
  playerRed: makeSprite(remap(SPR_PLAYER, { 'w': 'r', 'r': 'W', 'c': 'y' })),
  zako: [makeSprite(ZAKO_A), makeSprite(ZAKO_B)],
  goei: [makeSprite(GOEI_A), makeSprite(GOEI_B)],
  boss: [makeSprite(BOSS_A), makeSprite(BOSS_B)],
  bossHit: [makeSprite(toHit(BOSS_A)), makeSprite(toHit(BOSS_B))],
  life: null
};
// bullet sprites drawn directly with fillRect

/* ------------------------------ audio ------------------------------ */
let AC = null, master = null, muted = false;
function initAudio() {
  if (AC) { if (AC.state === 'suspended') AC.resume(); return; }
  try {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    master = AC.createGain(); master.gain.value = 0.25; master.connect(AC.destination);
  } catch (e) { AC = null; }
}
function tone(type, f0, f1, dur, vol, delay) {
  if (!AC || muted) return;
  const t = AC.currentTime + (delay || 0);
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type; o.frequency.setValueAtTime(f0, t);
  if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t + dur);
  g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(master); o.start(t); o.stop(t + dur + 0.02);
}
let noiseBuf = null;
function noise(dur, vol, f0, f1, delay) {
  if (!AC || muted) return;
  if (!noiseBuf) {
    noiseBuf = AC.createBuffer(1, AC.sampleRate, AC.sampleRate);
    const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  }
  const t = AC.currentTime + (delay || 0);
  const s = AC.createBufferSource(); s.buffer = noiseBuf; s.loop = true;
  const fl = AC.createBiquadFilter(); fl.type = 'lowpass';
  fl.frequency.setValueAtTime(f0, t); fl.frequency.exponentialRampToValueAtTime(Math.max(50, f1), t + dur);
  const g = AC.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  s.connect(fl); fl.connect(g); g.connect(master); s.start(t); s.stop(t + dur + 0.02);
}
const SFX = {
  shot() { tone('square', 1400, 300, 0.1, 0.18); },
  hit() { tone('square', 500, 200, 0.08, 0.2); noise(0.08, 0.15, 3000, 800); },
  kill() { noise(0.25, 0.4, 5000, 300); tone('sawtooth', 300, 60, 0.2, 0.15); },
  bossHit() { tone('square', 220, 120, 0.15, 0.25); tone('square', 330, 160, 0.15, 0.2, 0.05); },
  playerBoom() { noise(0.9, 0.6, 4000, 100); tone('sawtooth', 200, 30, 0.8, 0.25); },
  beamStart: null,
  jingle() {
    const n = [523, 659, 784, 1047, 784, 1047, 1319];
    n.forEach((f, i) => tone('square', f, f, 0.12, 0.15, i * 0.11));
  },
  capture() { [880, 660, 440, 330].forEach((f, i) => tone('triangle', f, f, 0.15, 0.25, i * 0.12)); },
  dock() { [523, 659, 784, 1047].forEach((f, i) => tone('square', f, f, 0.08, 0.15, i * 0.07)); },
  extra() { [988, 1319, 988, 1319, 1568].forEach((f, i) => tone('square', f, f, 0.09, 0.15, i * 0.09)); },
  dive() { tone('triangle', 900, 400, 0.12, 0.08); },
  bonus() { [660, 880, 1100, 1320].forEach((f, i) => tone('square', f, f, 0.1, 0.15, i * 0.09)); }
};
// continuous tractor beam sound
let beamOsc = null, beamGain = null;
function beamSound(on) {
  if (!AC) return;
  if (on && !beamOsc && !muted) {
    beamOsc = AC.createOscillator(); beamGain = AC.createGain();
    const lfo = AC.createOscillator(), lg = AC.createGain();
    beamOsc.type = 'sawtooth'; beamOsc.frequency.value = 180;
    lfo.frequency.value = 12; lg.gain.value = 60;
    lfo.connect(lg); lg.connect(beamOsc.frequency);
    beamGain.gain.value = 0.12;
    beamOsc.connect(beamGain); beamGain.connect(master);
    beamOsc.start(); lfo.start(); beamOsc._lfo = lfo;
  } else if (!on && beamOsc) {
    try { beamOsc.stop(); beamOsc._lfo.stop(); } catch (e) {}
    beamOsc = null; beamGain = null;
  }
}

/* ------------------------------ input ------------------------------ */
const keys = {};
let pressedEnter = false, pressedP = false;
window.addEventListener('keydown', e => {
  initAudio();
  if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space'].includes(e.code)) e.preventDefault();
  if (!keys[e.code]) {
    if (e.code === 'Enter') pressedEnter = true;
    if (e.code === 'KeyP') pressedP = true;
    if (e.code === 'KeyM') { muted = !muted; if (muted) beamSound(false); }
    if (e.code === 'Space') keys.spaceEdge = true;
  }
  keys[e.code] = true;
});
window.addEventListener('keyup', e => { keys[e.code] = false; });
window.addEventListener('blur', () => { for (const k in keys) keys[k] = false; });

/* ------------------------------ helpers ------------------------------ */
const rnd = (a, b) => a + Math.random() * (b - a);
const rndi = (a, b) => Math.floor(rnd(a, b + 1));
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
function pad(n, l) { n = String(n); while (n.length < l) n = ' ' + n; return n; }

/* ------------------------------ font ------------------------------ */
// Tiny 5x7 bitmap font rendered to cached canvases per colour.
const FONT = {
'A':["01110","10001","10001","11111","10001","10001","10001"],
'B':["11110","10001","10001","11110","10001","10001","11110"],
'C':["01110","10001","10000","10000","10000","10001","01110"],
'D':["11110","10001","10001","10001","10001","10001","11110"],
'E':["11111","10000","10000","11110","10000","10000","11111"],
'F':["11111","10000","10000","11110","10000","10000","10000"],
'G':["01110","10001","10000","10111","10001","10001","01111"],
'H':["10001","10001","10001","11111","10001","10001","10001"],
'I':["01110","00100","00100","00100","00100","00100","01110"],
'J':["00111","00010","00010","00010","00010","10010","01100"],
'K':["10001","10010","10100","11000","10100","10010","10001"],
'L':["10000","10000","10000","10000","10000","10000","11111"],
'M':["10001","11011","10101","10101","10001","10001","10001"],
'N':["10001","11001","10101","10011","10001","10001","10001"],
'O':["01110","10001","10001","10001","10001","10001","01110"],
'P':["11110","10001","10001","11110","10000","10000","10000"],
'Q':["01110","10001","10001","10001","10101","10010","01101"],
'R':["11110","10001","10001","11110","10100","10010","10001"],
'S':["01111","10000","10000","01110","00001","00001","11110"],
'T':["11111","00100","00100","00100","00100","00100","00100"],
'U':["10001","10001","10001","10001","10001","10001","01110"],
'V':["10001","10001","10001","10001","10001","01010","00100"],
'W':["10001","10001","10001","10101","10101","11011","10001"],
'X':["10001","10001","01010","00100","01010","10001","10001"],
'Y':["10001","10001","01010","00100","00100","00100","00100"],
'Z':["11111","00001","00010","00100","01000","10000","11111"],
'0':["01110","10001","10011","10101","11001","10001","01110"],
'1':["00100","01100","00100","00100","00100","00100","01110"],
'2':["01110","10001","00001","00010","00100","01000","11111"],
'3':["11110","00001","00001","01110","00001","00001","11110"],
'4':["00010","00110","01010","10010","11111","00010","00010"],
'5':["11111","10000","11110","00001","00001","10001","01110"],
'6':["00110","01000","10000","11110","10001","10001","01110"],
'7':["11111","00001","00010","00100","01000","01000","01000"],
'8':["01110","10001","10001","01110","10001","10001","01110"],
'9':["01110","10001","10001","01111","00001","00010","01100"],
'-':["00000","00000","00000","11111","00000","00000","00000"],
'.':["00000","00000","00000","00000","00000","01100","01100"],
'!':["00100","00100","00100","00100","00100","00000","00100"],
'%':["11001","11010","00010","00100","01000","01011","10011"],
':':["00000","01100","01100","00000","01100","01100","00000"],
'=':["00000","00000","11111","00000","11111","00000","00000"],
'/':["00001","00010","00010","00100","01000","01000","10000"],
'*':["00000","10101","01110","11111","01110","10101","00000"],
' ':["00000","00000","00000","00000","00000","00000","00000"]
};
const fontCache = {};
function glyph(ch, col) {
  const key = ch + col;
  if (fontCache[key]) return fontCache[key];
  const c = document.createElement('canvas'); c.width = 5; c.height = 7;
  const g = c.getContext('2d'); g.fillStyle = col;
  const d = FONT[ch] || FONT[' '];
  for (let y = 0; y < 7; y++) for (let x = 0; x < 5; x++) if (d[y][x] === '1') g.fillRect(x, y, 1, 1);
  return fontCache[key] = c;
}
function text(str, x, y, col, align) {
  str = String(str).toUpperCase();
  const w = str.length * 8;
  if (align === 'center') x = Math.round(x - w / 2); else if (align === 'right') x = x - w;
  for (let i = 0; i < str.length; i++) ctx.drawImage(glyph(str[i], col || '#fff'), x + i * 8, y);
}

/* ------------------------------ state ------------------------------ */
const STATE = { TITLE: 0, STAGE_INTRO: 1, PLAY: 2, CHALLENGE_END: 3, GAMEOVER: 4, RESULTS: 5 };
const game = {
  mode: STATE.TITLE, t: 0, score: 0, high: 0, lives: 3, stage: 0,
  nextExtra: 20000, shots: 0, hits: 0, paused: false, timer: 0,
  flash: 0
};
try { game.high = parseInt(localStorage.getItem('galagaHigh') || '0', 10) || 0; } catch (e) {}
function saveHigh() { try { localStorage.setItem('galagaHigh', String(game.high)); } catch (e) {} }

let player, enemies, bullets, pbullets, explosions, popups, stars, formation, beam, freed;
let stageInfo;

// Stars: 3 layers, coloured, twinkling, scrolling downward
stars = [];
const STAR_COLS = ['#ffffff', '#ff4040', '#4080ff', '#40ff40', '#ffff40', '#ff40ff', '#40ffff'];
for (let i = 0; i < 90; i++) stars.push({
  x: Math.random() * W, y: Math.random() * H, sp: [0.25, 0.5, 0.9][i % 3],
  col: STAR_COLS[rndi(0, STAR_COLS.length - 1)], ph: Math.random() * 100, rate: rnd(0.05, 0.2)
});

/* ------------------------------ formation geometry ------------------------------ */
// Slot grid: 10 columns, 6 rows. Row 0 boss/goei...
// Arcade layout: row0: 4 bosses (cols 3..6), rows1-2: goei 8 each (cols 1..8)... we use 16 goei = 2 rows of 8,
// rows3-4: 10 zako each.
const COL_SP = 16, ROW_SP = 16, FORM_Y = 50;
const FORM_CX = W / 2;
function slotBase(row, col) {
  return { x: FORM_CX + (col - 4.5) * COL_SP, y: FORM_Y + row * ROW_SP };
}
// breathing / sway state
formation = { sway: 0, swayDir: 1, breathe: 0, breatheT: 0, complete: false, filling: true };
function slotPos(e) {
  const b = slotBase(e.row, e.col);
  const k = formation.complete ? (1 + 0.28 * Math.sin(formation.breatheT)) : 1;
  const off = formation.complete ? 0 : 0; // sway applies in both
  return {
    x: FORM_CX + (b.x - FORM_CX) * k + formation.sway,
    y: FORM_Y + (b.y - FORM_Y) * (formation.complete ? (1 + 0.18 * Math.sin(formation.breatheT)) : 1)
  };
}

/* ------------------------------ paths ------------------------------ */
// Paths are lists of waypoints; entities follow them with Catmull-Rom splines at constant speed.
function catmull(p0, p1, p2, p3, t) {
  const t2 = t * t, t3 = t2 * t;
  return {
    x: 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3),
    y: 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3)
  };
}
// Build a polyline (dense) from control points for constant-speed travel
function buildPath(ctrl, mirror) {
  const pts = ctrl.map(p => ({ x: mirror ? W - p[0] : p[0], y: p[1] }));
  const ext = [pts[0], ...pts, pts[pts.length - 1]];
  const dense = [];
  for (let i = 1; i < ext.length - 2; i++) {
    for (let s = 0; s < 24; s++) dense.push(catmull(ext[i - 1], ext[i], ext[i + 1], ext[i + 2], s / 24));
  }
  dense.push(pts[pts.length - 1]);
  const lens = [0];
  for (let i = 1; i < dense.length; i++) lens.push(lens[i - 1] + Math.hypot(dense[i].x - dense[i - 1].x, dense[i].y - dense[i - 1].y));
  return { pts: dense, lens, total: lens[lens.length - 1] };
}
function pathAt(p, d) {
  if (d <= 0) return { x: p.pts[0].x, y: p.pts[0].y, a: 0 };
  if (d >= p.total) { const l = p.pts.length - 1; return { x: p.pts[l].x, y: p.pts[l].y, a: 0 }; }
  let lo = 0, hi = p.lens.length - 1;
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (p.lens[m] <= d) lo = m; else hi = m; }
  const f = (d - p.lens[lo]) / Math.max(0.0001, p.lens[hi] - p.lens[lo]);
  const a = p.pts[lo], b = p.pts[hi];
  return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f, a: Math.atan2(b.y - a.y, b.x - a.x) };
}
// Entry path templates (control points on left side; mirrored for right)
const ENTRY_PATHS = {
  // swoop from top-left, loop down, rise into formation
  A: [[80, -10], [90, 60], [60, 130], [30, 170], [50, 210], [100, 200], [110, 150], [100, 100]],
  // from side, sweeping across
  B: [[-10, 150], [40, 140], [100, 160], [150, 190], [170, 150], [140, 110], [110, 100]],
  // from top, wide arc
  C: [[110, -10], [120, 40], [180, 90], [200, 150], [160, 200], [100, 190], [95, 130], [100, 100]],
  // from bottom-side rising
  D: [[-10, 250], [50, 230], [90, 180], [70, 130], [40, 110], [70, 80], [100, 90]]
};
const entryCache = {};
function getEntry(name, mirror) {
  const k = name + (mirror ? 'm' : '');
  return entryCache[k] || (entryCache[k] = buildPath(ENTRY_PATHS[name], mirror));
}
// Challenging stage loop patterns
const CH_PATHS = {
  A: [[110, -10], [112, 60], [60, 110], [30, 160], [60, 190], [90, 150], [60, 110], [30, 70], [60, 40], [120, 110], [180, 200], [200, 260], [190, 310]],
  B: [[-10, 60], [60, 70], [130, 100], [170, 150], [150, 200], [100, 190], [90, 140], [130, 120], [190, 180], [210, 240], [200, 310]],
  C: [[110, -10], [100, 50], [160, 100], [190, 160], [150, 210], [100, 180], [140, 130], [190, 90], [215, 40], [170, 10], [100, 60], [60, 140], [30, 220], [20, 310]],
  D: [[-10, 150], [50, 130], [110, 150], [150, 130], [110, 90], [70, 130], [110, 190], [160, 230], [200, 280], [210, 320]],
  E: [[110, -10], [60, 70], [30, 130], [60, 180], [110, 150], [160, 180], [190, 130], [160, 70], [110, 100], [60, 170], [40, 240], [50, 320]]
};

/* ------------------------------ entities ------------------------------ */
const TYPE = { ZAKO: 0, GOEI: 1, BOSS: 2 };
const ST = { WAIT: 0, ENTER: 1, SLOT: 2, DIVE: 3, RETURN: 4, BEAM: 5, CHALLENGE: 6, DEAD: 9 };

function newEnemy(type, row, col) {
  return {
    type, row, col, st: ST.WAIT, x: -50, y: -50, a: 0, hp: type === TYPE.BOSS ? 2 : 1,
    path: null, pd: 0, delay: 0, speed: 2, diveT: 0, escorts: [], leader: null,
    captive: null, // captured fighter state if boss holds one: {x,y,hostile}
    flap: Math.random() * 10, shots: 0, nextShot: 0, beamT: 0, trk: 0, w: 13, h: 10,
    dive: null, wave: 0
  };
}
function enemyBox(e) {
  const w = e.type === TYPE.ZAKO ? 11 : 13, h = e.type === TYPE.ZAKO ? 8 : 10;
  return { x: e.x - w / 2, y: e.y - h / 2, w, h };
}
function boxHit(a, b) { return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y; }

/* ------------------------------ stage setup ------------------------------ */
function isChallenge(n) { return n >= 3 && (n - 3) % 4 === 0; }

function startStage(n) {
  game.stage = n;
  enemies = []; bullets = []; pbullets = []; explosions = []; popups = [];
  beam = null; freed = null;
  formation.sway = 0; formation.swayDir = 1; formation.breatheT = 0; formation.complete = false; formation.filling = true;
  stageInfo = {
    challenge: isChallenge(n), waveIdx: 0, spawnT: 0, hits: 0, waveKills: [0, 0, 0, 0, 0], waveSize: [0, 0, 0, 0, 0],
    enemiesDone: false, diveTimer: 90, beamAllowed: true, lastKill: 0, captiveBoss: null
  };
  if (stageInfo.challenge) buildChallenge(n); else buildWaves(n);
  game.mode = STATE.PLAY;
  stageInfo.ready = 0;
}

// Wave compositions for normal stages. 5 groups of 8 (arcade style), entering sequentially.
function buildWaves(n) {
  const list = [];
  // slots
  const bosses = [], goei = [], zako = [];
  for (let c = 3; c <= 6; c++) bosses.push([0, c]);
  for (let r = 1; r <= 2; r++) for (let c = 1; c <= 8; c++) goei.push([r, c]);
  for (let r = 3; r <= 4; r++) for (let c = 0; c <= 9; c++) zako.push([r, c]);
  const mk = (type, rc) => newEnemy(type, rc[0], rc[1]);
  // group definitions: [path, mirror, enemies]
  // arcade-like: wave1 4 goei+4 boss? We use: W1: 4 bosses+4 goei (path A), W2: 8 goei (B), W3: 8 zako (C), W4: 8 zako (D mirrored), W5: 4 goei... 
  const groups = [];
  groups.push({ path: 'A', mirror: false, units: [...bosses.map(r => mk(TYPE.BOSS, r)), ...goei.slice(0, 4).map(r => mk(TYPE.GOEI, r))] });
  groups.push({ path: 'B', mirror: false, units: goei.slice(4, 12).map(r => mk(TYPE.GOEI, r)) });
  groups.push({ path: 'C', mirror: true, units: zako.slice(0, 8).map(r => mk(TYPE.ZAKO, r)) });
  groups.push({ path: 'D', mirror: false, units: zako.slice(8, 16).map(r => mk(TYPE.ZAKO, r)) });
  groups.push({ path: 'B', mirror: true, units: [...goei.slice(12, 16).map(r => mk(TYPE.GOEI, r)), ...zako.slice(16, 20).map(r => mk(TYPE.ZAKO, r))] });
  const spd = 2.0 + Math.min(n, 20) * 0.04;
  let t = 30;
  groups.forEach((g, gi) => {
    g.units.forEach((e, i) => {
      e.path = getEntry(g.path, g.mirror); e.pd = 0; e.delay = t + i * 9; e.speed = spd; e.st = ST.WAIT; e.wave = gi;
      e.enterShoot = n >= 2;
      enemies.push(e);
    });
    t += 8 * 9 + 70;
  });
}

function buildChallenge(n) {
  const kinds = [TYPE.ZAKO, TYPE.GOEI, TYPE.ZAKO, TYPE.GOEI, TYPE.BOSS];
  const names = ['A', 'B', 'C', 'D', 'E'], mir = [false, true, false, true, false];
  const spd = 2.4 + Math.min(n / 4, 3) * 0.1;
  let t = 30;
  for (let w = 0; w < 5; w++) {
    const type = (n >= 7 && w >= 3) ? TYPE.BOSS : (n >= 3 && w === 4 ? TYPE.GOEI : kinds[w % 2 ? 1 : 0]);
    const path = buildPath(CH_PATHS[names[w]], mir[w]);
    for (let i = 0; i < 8; i++) {
      const e = newEnemy(type === TYPE.BOSS ? TYPE.GOEI : type, 0, 0);
      e.st = ST.WAIT; e.path = path; e.pd = 0; e.delay = t + i * 8; e.speed = spd; e.wave = w; e.challenge = true;
      e.hp = 1; enemies.push(e);
      stageInfo.waveSize[w]++;
    }
    t += 8 * 8 + 40;
  }
}

/* ------------------------------ player ------------------------------ */
function newPlayer() {
  return { x: W / 2, y: 262, alive: true, dual: false, respawn: 0, captured: false, dying: 0, invuln: 0, cooldown: 0, ready: 0 };
}
const PLAYER_SPEED = 1.5;
function playerBoxes() {
  if (!player.alive) return [];
  const bx = [{ x: player.x - 6, y: player.y - 7, w: 13, h: 14, half: 0 }];
  if (player.dual) { bx[0].x = player.x - 6 - 7.5; bx.push({ x: player.x - 6 + 7.5, y: player.y - 7, w: 13, h: 14, half: 1 }); }
  return bx;
}
function playerMinX() { return player.dual ? 15 : 8; }
function playerMaxX() { return player.dual ? W - 15 : W - 8; }

function addScore(p) {
  const before = game.score;
  game.score += p;
  if (game.score > game.high) { game.high = game.score; }
  while (game.score >= game.nextExtra) {
    if (game.lives < 9) game.lives++;
    SFX.extra();
    game.nextExtra += (game.nextExtra === 20000 ? 70000 : 70000);
    if (game.nextExtra === 90000 && before < 20000) { /* ok */ }
  }
}
// Extra ships at 20,000 and every 70,000 thereafter (90,000, 160,000 ...). Handle thresholds precisely:
game.nextExtra = 20000;

function popup(x, y, str, col) { popups.push({ x, y, str, col: col || '#fff', t: 60 }); }
function explode(x, y, big) { explosions.push({ x, y, t: 0, big: !!big }); }

function startRespawn() {
  player.alive = false; player.respawn = 150;
  player.dual = false;
}

/* ------------------------------ firing ------------------------------ */
function playerFire() {
  const max = 2;
  const need = player.dual ? 2 : 1;
  if (pbullets.length + need > (player.dual ? 4 : max)) return;
  if (!player.dual && pbullets.length >= 2) return;
  if (player.dual && pbullets.length >= 4) return;
  if (player.dual) {
    pbullets.push({ x: player.x - 7.5, y: player.y - 12 });
    pbullets.push({ x: player.x + 7.5, y: player.y - 12 });
    game.shots += 2;
  } else {
    pbullets.push({ x: player.x, y: player.y - 12 });
    game.shots++;
  }
  SFX.shot();
}
function enemyFire(e) {
  if (!player.alive) return;
  const dx = player.x - e.x, dy = player.y - e.y;
  if (dy < 20) return;
  const sp = 1.6 + Math.min(game.stage, 20) * 0.025;
  const ang = Math.atan2(dy, dx + rnd(-12, 12));
  bullets.push({ x: e.x, y: e.y + 4, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp });
}

/* ------------------------------ dive logic ------------------------------ */
function inFormation() { return enemies.filter(e => e.st === ST.SLOT); }
function diving() { return enemies.filter(e => e.st === ST.DIVE || e.st === ST.BEAM || e.st === ST.RETURN); }

// Dive path generator: dynamic curve through points that aim at player's x
function makeDivePath(e, startX, startY, loopSide) {
  const dir = loopSide;
  const px = player && player.alive ? player.x : W / 2;
  const pts = [
    [startX, startY],
    [startX + dir * 22, startY - 14],
    [startX + dir * 30, startY + 10],
    [startX + dir * 10, startY + 30],
    [startX - dir * 5, startY + 22],
    [clamp(px + rnd(-30, 30), 20, W - 20), 130 + rnd(0, 30)],
    [clamp(px + rnd(-40, 40), 15, W - 15), 200],
    [clamp(px + rnd(-50, 50), 10, W - 10), 250],
    [clamp(px + rnd(-50, 50), 10, W - 10), 310]
  ];
  const ext = [pts[0], ...pts, pts[pts.length - 1]];
  const dense = [];
  for (let i = 1; i < ext.length - 2; i++) for (let s = 0; s < 20; s++) dense.push(catmull(
    { x: ext[i - 1][0], y: ext[i - 1][1] }, { x: ext[i][0], y: ext[i][1] }, { x: ext[i + 1][0], y: ext[i + 1][1] }, { x: ext[i + 2][0], y: ext[i + 2][1] }, s / 20));
  dense.push({ x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] });
  const lens = [0];
  for (let i = 1; i < dense.length; i++) lens.push(lens[i - 1] + Math.hypot(dense[i].x - dense[i - 1].x, dense[i].y - dense[i - 1].y));
  return { pts: dense, lens, total: lens[lens.length - 1] };
}

function launchDive(e, escorts) {
  const loop = e.x < W / 2 ? -1 : 1;
  e.st = ST.DIVE; e.path = makeDivePath(e, e.x, e.y, loop); e.pd = 0;
  e.speed = 2.0 + Math.min(game.stage, 20) * 0.045;
  e.shots = 0; e.nextShot = rndi(20, 40);
  e.dive = { escorts: escorts || [], ox: 0 };
  SFX.dive();
}
function launchBeamDive(e) {
  e.st = ST.DIVE; e.beamDive = true; e.beamPhase = 0;
  const loop = e.x < W / 2 ? -1 : 1;
  const tx = clamp(player.alive ? player.x : W / 2, 50, W - 50);
  const pts = [[e.x, e.y], [e.x + loop * 20, e.y - 12], [e.x + loop * 25, e.y + 12], [tx, 150], [tx, 190]];
  const path = buildPathRaw(pts);
  e.path = path; e.pd = 0; e.speed = 1.6;
  e.dive = { escorts: [], ox: 0 };
}
function buildPathRaw(pts) {
  const ext = [pts[0], ...pts, pts[pts.length - 1]];
  const dense = [];
  for (let i = 1; i < ext.length - 2; i++) for (let s = 0; s < 20; s++) dense.push(catmull(
    { x: ext[i - 1][0], y: ext[i - 1][1] }, { x: ext[i][0], y: ext[i][1] }, { x: ext[i + 1][0], y: ext[i + 1][1] }, { x: ext[i + 2][0], y: ext[i + 2][1] }, s / 20));
  dense.push({ x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] });
  const lens = [0];
  for (let i = 1; i < dense.length; i++) lens.push(lens[i - 1] + Math.hypot(dense[i].x - dense[i - 1].x, dense[i].y - dense[i - 1].y));
  return { pts: dense, lens, total: lens[lens.length - 1] };
}

function chooseDive() {
  if (!player.alive || player.respawn > 0) return;
  const f = inFormation();
  if (!f.length) return;
  const maxDivers = Math.min(2 + Math.floor(game.stage / 2), 6);
  if (diving().length >= maxDivers) return;
  const hasBeam = enemies.some(e => e.beamDive || e.st === ST.BEAM);
  // pick a random formation enemy, bias to front rows
  const bosses = f.filter(e => e.type === TYPE.BOSS && !e.escorting);
  // tractor beam attempt: boss without captive, player not dual, no captured ship currently freed etc.
  if (bosses.length && !hasBeam && !player.dual && Math.random() < 0.35 && !bosses.every(b => b.captive) && f.length < 38) {
    const cand = bosses.filter(b => !b.captive);
    if (cand.length && stageInfo.beamAllowed && game.lives >= 1 && !(freed)) {
      launchBeamDive(cand[rndi(0, cand.length - 1)]);
      return;
    }
  }
  if (bosses.length && Math.random() < 0.4) {
    const b = bosses[rndi(0, bosses.length - 1)];
    // escorts: goei near the boss
    const gs = f.filter(e => e.type === TYPE.GOEI).sort((p, q) => Math.abs(p.col - b.col) - Math.abs(q.col - b.col)).slice(0, rndi(0, 2));
    launchDive(b, gs);
    gs.forEach(g => { g.st = ST.DIVE; g.escortOf = b; g.escortSlot = (gs.indexOf(g) === 0 ? -1 : 1); g.escorting = true; g.path = null; g.shots = 0; g.nextShot = rndi(20, 40); });
    b.escortList = gs;
    return;
  }
  const rest = f.filter(e => e.type !== TYPE.BOSS);
  if (rest.length) {
    const e = rest[rndi(0, rest.length - 1)];
    launchDive(e);
    // sometimes a second one follows
    if (Math.random() < 0.3 && rest.length > 1) {
      const o = rest[rndi(0, rest.length - 1)]; if (o !== e && o.st === ST.SLOT) launchDive(o);
    }
  }
}

/* ------------------------------ kills ------------------------------ */
function killEnemy(e, byPlayer) {
  e.st = ST.DEAD;
  explode(e.x, e.y, false);
  SFX.kill();
  if (e.captive) {
    // boss destroyed with its captive
    if (e.st === ST.DEAD && e.captive) {
      if (e.wasDiving) {
        // captive freed
        freed = { x: e.captive.x, y: e.captive.y, vy: 0, state: 'fly' };
        popup(e.x, e.y - 8, 'FIGHTER RESCUED', '#20e0ff');
      } else {
        // destroyed
        explode(e.captive.x, e.captive.y, false);
        popup(e.x, e.y, 'FIGHTER LOST', '#ff4040');
      }
      e.captive = null;
    }
  }
}

function scoreFor(e, diving) {
  if (e.type === TYPE.ZAKO) return diving ? 100 : 50;
  if (e.type === TYPE.GOEI) return diving ? 160 : 80;
  return diving ? 400 : 150;
}

function hitEnemy(e, b) {
  const wasDiving = e.st === ST.DIVE || e.st === ST.RETURN || e.st === ST.BEAM;
  if (e.challenge) {
    game.hits++; stageInfo.hits++; stageInfo.waveKills[e.wave]++;
    addScore(100); popup(e.x, e.y, '100');
    e.st = ST.DEAD; explode(e.x, e.y); SFX.kill(); game.lastKill = game.t;
    return;
  }
  game.hits++;
  if (e.type === TYPE.BOSS && e.hp > 1) {
    e.hp--; SFX.bossHit(); explode(e.x, e.y + 2, false);
    return;
  }
  if (e.type === TYPE.BOSS) { SFX.bossHit(); }
  let pts = scoreFor(e, wasDiving);
  if (e.type === TYPE.BOSS && wasDiving) {
    const n = (e.escortList || []).filter(g => g.st !== ST.DEAD).length;
    pts = n === 0 ? 400 : n === 1 ? 800 : 1600;
  }
  addScore(pts);
  popup(e.x, e.y, String(pts), pts >= 800 ? '#ffe020' : '#fff');
  e.wasDiving = wasDiving;
  if (e.beamDive || e.st === ST.BEAM) { beamSound(false); beam = null; }
  killEnemy(e, true);
  if (e.escortList) e.escortList.forEach(g => { g.escortOf = null; });
}

/* ------------------------------ player death ------------------------------ */
function killPlayer(half) {
  SFX.playerBoom();
  if (player.dual) {
    // lose one half only
    const px = player.x + (half === 0 ? -7.5 : 7.5);
    explode(px, player.y, true);
    player.dual = false;
    player.x += half === 0 ? 7.5 : -7.5;
    player.invuln = 90;
    return;
  }
  explode(player.x, player.y, true);
  game.lives--;
  player.dying = 1;
  startRespawn();
  beamSound(false);
  if (beam) { beam = null; }
  // abort any beam diver
  enemies.forEach(e => { if (e.st === ST.BEAM) { e.st = ST.DIVE; e.beamDive = false; e.pd = e.path.total * 0.6; } });
}

/* ------------------------------ update ------------------------------ */
function updateStars() {
  for (const s of stars) {
    s.y += s.sp; if (s.y >= H) { s.y -= H; s.x = Math.random() * W; }
    s.ph += s.rate;
  }
}

function updateFormationMotion() {
  // sway
  formation.sway += formation.swayDir * 0.25;
  if (Math.abs(formation.sway) > 18) formation.swayDir *= -1;
  if (formation.complete) formation.breatheT += 0.03;
}

function updateEnemies() {
  const t = game.t;
  let allEntered = true;
  const stg = game.stage;
  for (const e of enemies) {
    e.flap += 0.12;
    switch (e.st) {
      case ST.WAIT:
        allEntered = false;
        if (--e.delay <= 0) { e.st = ST.ENTER; e.pd = 0; if (e.challenge) e.st = ST.CHALLENGE; }
        break;
      case ST.ENTER: {
        allEntered = false;
        e.pd += e.speed;
        const p = pathAt(e.path, e.pd);
        e.x = p.x; e.y = p.y; e.a = p.a;
        if (e.enterShoot && Math.random() < 0.004 && e.y < 190 && e.y > 30) enemyFire(e);
        if (e.pd >= e.path.total) {
          e.st = ST.SLOT; e.slotBlend = 0;
        }
        break;
      }
      case ST.CHALLENGE: {
        e.pd += e.speed;
        const p = pathAt(e.path, e.pd);
        e.x = p.x; e.y = p.y; e.a = p.a;
        if (e.pd >= e.path.total) e.st = ST.DEAD, e.gone = true;
        allEntered = false;
        break;
      }
      case ST.SLOT: {
        const sp = slotPos(e);
        if (e.slotBlend !== undefined && e.slotBlend < 1) {
          e.slotBlend = Math.min(1, e.slotBlend + 0.08);
          e.x += (sp.x - e.x) * 0.25 * (e.slotBlend + 0.2); e.y += (sp.y - e.y) * 0.25 * (e.slotBlend + 0.2);
          if (Math.abs(sp.x - e.x) < 1.5 && Math.abs(sp.y - e.y) < 1.5) e.slotBlend = 1;
        } else { e.x = sp.x; e.y = sp.y; }
        e.a = Math.PI / 2;
        if (e.captive) { e.captive.x = e.x; e.captive.y = e.y - 14; }
        break;
      }
      case ST.DIVE: {
        if (e.escorting && e.escortOf && e.escortOf.st !== ST.DEAD && (e.escortOf.st === ST.DIVE || e.escortOf.st === ST.BEAM)) {
          const L = e.escortOf;
          e.x += (L.x + e.escortSlot * 16 - e.x) * 0.15;
          e.y += (L.y - 10 - e.y) * 0.15;
          e.a = L.a;
          if (--e.nextShot <= 0 && e.shots < 2 && e.y < 200) { enemyFire(e); e.shots++; e.nextShot = rndi(25, 50); }
          break;
        }
        if (e.escorting) { // leader gone -> become independent diver
          e.escorting = false; e.escortOf = null;
          e.path = makeDivePath(e, e.x, e.y, e.x < W / 2 ? -1 : 1); e.pd = 0; e.speed = 2.0;
          e.nextShot = 20; e.shots = 0;
        }
        const wasPd = e.pd;
        if (e.beamDive && e.beamPhase === 0) {
          e.pd += e.speed;
          if (e.pd >= e.path.total) {
            // start tractor beam
            e.st = ST.BEAM; e.beamT = 0; e.beamPhase = 1;
            beam = { boss: e, t: 0 };
            beamSound(true);
            break;
          }
        } else e.pd += e.speed;
        const p = pathAt(e.path, e.pd);
        e.x = p.x; e.y = p.y; e.a = p.a;
        if (e.captive) { e.captive.x = e.x; e.captive.y = e.y - 14; }
        if (--e.nextShot <= 0 && e.shots < 3 && e.y < 210 && e.y > 40 && !e.beamDive) {
          enemyFire(e); e.shots++; e.nextShot = rndi(18, 40);
        }
        if (e.pd >= e.path.total || e.y > H + 20) {
          // leaves bottom: re-enter from top and return to slot
          e.st = ST.RETURN; e.x = clamp(e.x, 10, W - 10); e.y = -12; e.beamDive = false;
          if (e.escortList) e.escortList.forEach(g => { if (g.st === ST.DIVE) { g.st = ST.RETURN; g.escorting = false; g.x = e.x + g.escortSlot * 16; g.y = -12; } });
          e.escortList = null;
        }
        break;
      }
      case ST.BEAM: {
        e.a = Math.PI / 2;
        e.beamT++;
        if (beam && beam.boss === e) {
          beam.t = e.beamT;
          // check capture
          if (player.alive && !player.dual && e.beamT > 20 && e.beamT < 150 && !player.captured) {
            const bw = Math.min(46, 8 + e.beamT * 0.9) / 2;
            if (Math.abs(player.x - e.x) < bw && player.y > e.y) {
              player.captured = true; player.captureBoss = e; player.capT = 0;
              e.captureTarget = true;
            }
          }
        }
        if (e.beamT > 170 || (player.captured && e.captureTarget && player.capDone)) {
          beamSound(false);
          if (e.captureTarget && player.capDone) {
            // boss keeps captive and dives back to formation
            e.captive = { x: e.x, y: e.y - 14, hostile: false };
            e.captureTarget = false; e.beamDive = false;
            player.captured = false; player.capDone = false;
            e.st = ST.RETURN; e.y = Math.min(e.y, 200);
          } else {
            e.beamDive = false;
            e.st = ST.RETURN;
            e.x = clamp(e.x, 10, W - 10);
          }
          beam = null;
        }
        break;
      }
      case ST.RETURN: {
        const sp = slotPos(e);
        // from top: approach slot
        if (e.y < 0 && e.x !== sp.x && e.y === -12) { e.x = sp.x; }
        const dx = sp.x - e.x, dy = sp.y - e.y, d = Math.hypot(dx, dy);
        const v = 2.4;
        if (d < v + 0.5) { e.x = sp.x; e.y = sp.y; e.st = ST.SLOT; e.slotBlend = 1; }
        else { e.x += dx / d * v; e.y += dy / d * v; e.a = Math.atan2(dy, dx); }
        if (e.captive) { e.captive.x = e.x; e.captive.y = e.y - 14; }
        break;
      }
    }
  }
  // Remove dead
  enemies = enemies.filter(e => e.st !== ST.DEAD);
  // formation completion
  if (!stageInfo.challenge) {
    if (allEntered && !enemies.some(e => e.st === ST.WAIT || e.st === ST.ENTER)) formation.complete = true;
  }
}

function updateCapture() {
  if (!player.captured) return;
  const b = player.captureBoss;
  if (!b || b.st === ST.DEAD) { player.captured = false; return; }
  player.capT++;
  player.x += (b.x - player.x) * 0.06;
  player.y -= 1.0;
  player.spin = (player.spin || 0) + 0.3;
  if (player.y <= b.y + 14) {
    // fully captured
    player.capDone = true;
    SFX.capture();
    // player loses ship
    explodeSilent();
    game.lives--;
    player.alive = false; player.respawn = 150; player.captured = false;
    player.dual = false;
    b.captive = { x: b.x, y: b.y - 14, hostile: false };
    b.captureTarget = false; b.capDone = false;
    beamSound(false); beam = null;
    b.beamDive = false; b.st = ST.RETURN; b.x = clamp(b.x, 10, W - 10);
    b.captiveJustTaken = true;
    popup(b.x, b.y - 20, 'FIGHTER CAPTURED', '#ff4040');
  }
}
function explodeSilent() {}

function updatePlayerBullets() {
  for (const b of pbullets) b.y -= 4.5;
  pbullets = pbullets.filter(b => b.y > -8 && !b.dead);
  // hit detection
  for (const b of pbullets) {
    const bb = { x: b.x - 1, y: b.y - 3, w: 2, h: 6 };
    for (const e of enemies) {
      if (e.st === ST.WAIT || e.st === ST.DEAD) continue;
      if (e.st === ST.ENTER && false) continue;
      if (boxHit(bb, enemyBox(e))) { b.dead = true; hitEnemy(e, b); break; }
    }
    if (b.dead) continue;
    // captive fighter hostile hit? captured fighters are shot via boss
  }
  pbullets = pbullets.filter(b => !b.dead);
}

function updateEnemyBullets() {
